  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
`

const MmrBadge = styled.span<{ $high?: boolean }>`
  margin-left: auto;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  color: ${p => (p.$high ? color('amber400') : DimTextColor())};
`

const MapPreview = styled.div`
